CREATE OR REPLACE FUNCTION public.my_expirations()
 RETURNS TABLE(scope text, source text, item_id uuid, member_id uuid, apparatus_id uuid, subject text, kind text, label text, cls text, expires_on date, days_until integer, bucket text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- B4C:expirations — the caller's own: their certs, credentials and assigned gear, ranked. Read-only.
declare v_dept uuid := public.my_department_id(); v_me uuid := public.my_member_id();
begin
  if v_dept is null or v_me is null then raise exception 'We could not match your login to a department.'; end if;
  return query select * from public.expiration_rows(v_dept, v_me);
end;
$function$

delete_cert(uuid).def:
CREATE OR REPLACE FUNCTION public.delete_cert(cert_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_dept_admin() then
    raise exception 'Not authorized to delete certifications';
  end if;

  delete from public.certs where id = cert_id and department_id = public.my_department_id();

  if not found then
    raise exception 'Certification not found';
  end if;
end;
$function$

is_muted(uuid,text).def:
CREATE OR REPLACE FUNCTION public.is_muted(p_member uuid, p_family text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enabled boolean;
begin
  IF p_family IS NULL OR p_family NOT IN ('certs','gear','maint','events','tasks','shifts') THEN
    RAISE EXCEPTION 'is_muted: unknown notification family %. A typo here would silently ignore a member''s opt-out.', coalesce(p_family, '<null>');
  END IF;

  select enabled into v_enabled
    from public.notification_prefs
   where member_id = p_member and family = p_family;

  -- ABSENCE MEANS ON, matching the client: a member who has never opened the
  -- preferences screen has no row, and no row is not an opt-out.
  return v_enabled is not null and v_enabled = false;
end;
$function$

delete_cert_type(uuid).def:
CREATE OR REPLACE FUNCTION public.delete_cert_type(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- B4C:cert catalog — remove a type from your department's catalog. Certs that used it keep their row; the FK
  -- (ON DELETE SET NULL) clears their cert_type_id, so they read exactly as an untyped cert does.
  declare v_dept uuid := public.my_department_id();
  begin
    if v_dept is null or not coalesce(public.is_dept_admin(), false) then
      raise exception 'Only a Department Admin can manage cert types.';
    end if;
    delete from public.cert_types where id = p_id and department_id = v_dept;
    if not found then raise exception 'That cert type is not in your department.'; end if;
  end;
  $function$

assign_cert_type(uuid,uuid).def:
CREATE OR REPLACE FUNCTION public.assign_cert_type(p_cert_id uuid, p_cert_type_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- B4C:cert catalog — link a cert to a type (or NULL to unlink). The cert AND the type must both be in the caller's
  -- department; a cross-department cert reads "not found", never revealing it exists elsewhere (as update_cert does).
  declare v_dept uuid := public.my_department_id();
  begin
    if v_dept is null or not coalesce(public.is_dept_admin(), false) then
      raise exception 'Only a Department Admin can assign cert types.';
    end if;
    if p_cert_type_id is not null and not exists (select 1 from public.cert_types where id = p_cert_type_id and department_id = v_dept) then
      raise exception 'That cert type is not in your department.';
    end if;
    update public.certs set cert_type_id = p_cert_type_id where id = p_cert_id and department_id = v_dept;
    if not found then raise exception 'Certification not found'; end if;
  end;
  $function$

update_cert(uuid,text,text).def:
CREATE OR REPLACE FUNCTION public.update_cert(cert_id uuid, new_name text, new_exp text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_dept_admin() then
    raise exception 'Not authorized to edit certifications';
  end if;

  if new_name is null or btrim(new_name) = '' then
    raise exception 'Certification name is required';
  end if;

  -- exp must be null/empty (no expiration) or a valid YYYY-MM string
  if new_exp is not null and btrim(new_exp) <> '' and not public.valid_exp_ym(new_exp) then
    raise exception 'Expiration must be a real month as YYYY-MM (e.g. 2027-06).';
  end if;

  update public.certs
  set name = btrim(new_name),
      exp  = case when new_exp is null or btrim(new_exp) = '' then null else new_exp end
  where id = cert_id and department_id = public.my_department_id();

  if not found then
    raise exception 'Certification not found';
  end if;
end;
$function$

add_standard_cert_type(uuid).def:
CREATE OR REPLACE FUNCTION public.add_standard_cert_type(p_standard_id uuid)
 RETURNS cert_types
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- B4C:standard certs — a Department Admin (or PA) copies a standard cert type into their OWN department's catalog. The
  -- copy is an ordinary cert_types row afterwards (edit via set_cert_type, delete via delete_cert_type).
  declare v_dept uuid := public.my_department_id(); v_me uuid := public.my_member_id();
          v_std public.standard_cert_types; v_row public.cert_types;
  begin
    if v_dept is null or not coalesce(public.is_dept_admin(), false) then
      raise exception 'Only a Department Admin can manage cert types.';
    end if;
    select * into v_std from public.standard_cert_types where id = p_standard_id;
    if not found then raise exception 'That standard cert type was not found.'; end if;
    begin
      insert into public.cert_types (department_id, name, never_expires, category, created_by, updated_by)
      values (v_dept, btrim(v_std.name), v_std.never_expires, v_std.category, v_me, v_me)
      returning * into v_row;
    exception when unique_violation then
      raise exception 'That cert type is already in your catalog.';
    end;
    return v_row;
  end;
  $function$

approve_cert_submission(uuid).def:
CREATE OR REPLACE FUNCTION public.approve_cert_submission(submission_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  sub public.cert_submissions;
  new_cert_id uuid;
begin
  if not public.is_dept_admin() then
    raise exception 'Not authorized to approve cert submissions';
  end if;
  select * into sub from public.cert_submissions where id = submission_id;
  if not found then
    raise exception 'Submission not found';
  end if;
  if sub.department_id is distinct from public.my_department_id() then
    raise exception 'Not in your department';
  end if;
  if sub.status <> 'pending' then
    raise exception 'Submission is not pending (current status: %)', sub.status;
  end if;
  insert into public.certs (id, department_id, member_id, name, exp, proof_path, created_at)
  values (gen_random_uuid(), sub.department_id, sub.member_id, sub.name, case when public.valid_exp_ym(sub.exp) then sub.exp end, sub.proof_path, now())
  returning id into new_cert_id;
  update public.cert_submissions
  set status = 'approved', reviewed_by = auth.uid(), reviewed_at = now()
  where id = submission_id;
  return new_cert_id;
end;
$function$

reject_cert_submission(uuid,text).def:
CREATE OR REPLACE FUNCTION public.reject_cert_submission(submission_id uuid, reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  sub public.cert_submissions;
begin
  -- same authority gate as approve
  if not public.is_dept_admin() then
    raise exception 'Not authorized to reject cert submissions';
  end if;

  select * into sub from public.cert_submissions where id = submission_id;

  if not found then
    raise exception 'Submission not found';
  end if;

  if sub.department_id is distinct from public.my_department_id() then
    raise exception 'Not in your department';
  end if;

  if sub.status <> 'pending' then
    raise exception 'Submission is not pending (current status: %)', sub.status;
  end if;

  update public.cert_submissions
  set status = 'rejected',
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      note = coalesce(reason, note)
  where id = submission_id;
end;
$function$

set_cert_type(uuid,text,boolean,text).def:
CREATE OR REPLACE FUNCTION public.set_cert_type(p_id uuid, p_name text, p_never_expires boolean, p_category text DEFAULT 'certification'::text)
 RETURNS cert_types
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- B4C:cert catalog — a Department Admin (or PA) adds (p_id NULL) or edits a cert type in their own department.
  declare v_dept uuid := public.my_department_id(); v_me uuid := public.my_member_id(); v_name text := btrim(coalesce(p_name, ''));
          v_cat text := coalesce(nullif(btrim(p_category), ''), 'certification'); v_row public.cert_types;
  begin
    if v_dept is null or not coalesce(public.is_dept_admin(), false) then
      raise exception 'Only a Department Admin can manage cert types.';
    end if;
    if v_name = '' then raise exception 'A cert type needs a name.'; end if;
    if v_cat not in ('certification', 'continuing_education') then raise exception 'Unknown category — use certification or continuing_education.'; end if;
    begin
      if p_id is null then
        insert into public.cert_types (department_id, name, never_expires, category, created_by, updated_by)
        values (v_dept, v_name, coalesce(p_never_expires, false), v_cat, v_me, v_me)
        returning * into v_row;
      else
        update public.cert_types
           set name = v_name, never_expires = coalesce(p_never_expires, false), category = v_cat, updated_by = v_me, updated_at = now()
         where id = p_id and department_id = v_dept
        returning * into v_row;
        if not found then raise exception 'That cert type is not in your department.'; end if;
      end if;
    exception when unique_violation then
      raise exception 'Your department already has a cert type named "%".', v_name;
    end;
    return v_row;
  end;
  $function$

set_readiness_requirement(text,uuid,bool.def:
CREATE OR REPLACE FUNCTION public.set_readiness_requirement(p_kind text, p_ref_id uuid DEFAULT NULL::uuid, p_required boolean DEFAULT true)
 RETURNS readiness_requirements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- B4C:scorecard — a Department Admin (or PA) sets the department's readiness standard: add / keep (required) or drop
-- from the count (required = false). Never touches the locked verification column.
declare v_dept uuid := public.my_department_id(); v_me uuid := public.my_member_id(); v_ref uuid := p_ref_id; v_row public.readiness_requirements;
begin
  if v_dept is null or not coalesce(public.is_dept_admin(), false) then
    raise exception 'Only a Department Admin can set the readiness standard.';
  end if;
  if p_kind is null or p_kind not in ('credential_license', 'credential_med_card', 'credential_fit_test', 'qualification_type', 'document', 'cert_type') then
    raise exception 'Unknown requirement type.';
  end if;
  if p_kind like 'credential\_%' then
    if v_ref is not null then raise exception 'A credential requirement is the credential type itself — no item to pick.'; end if;
  elsif p_kind = 'qualification_type' then
    if v_ref is null or not exists (select 1 from public.qualification_types where id = v_ref and department_id = v_dept) then
      raise exception 'That qualification is not set up in your department.';
    end if;
  elsif p_kind = 'cert_type' then   -- cert catalog (Slice B): a cert type of this department
    if v_ref is null or not exists (select 1 from public.cert_types where id = v_ref and department_id = v_dept) then
      raise exception 'That cert type is not set up in your department.';
    end if;
  else   -- document: a series id, or any document row of it (mapped through documents.series_id)
    if v_ref is not null and not exists (select 1 from public.document_series where series_id = v_ref and department_id = v_dept) then
      select d.series_id into v_ref from public.documents d where d.id = p_ref_id and d.department_id = v_dept;
    end if;
    if v_ref is null or not exists (select 1 from public.document_series where series_id = v_ref and department_id = v_dept) then
      raise exception 'That document is not in your department.';
    end if;
  end if;
  insert into public.readiness_requirements (department_id, kind, ref_id, required, created_by, updated_by)
  values (v_dept, p_kind, v_ref, coalesce(p_required, true), v_me, v_me)
  on conflict (department_id, kind, ref_id) do update set required = excluded.required, updated_by = excluded.updated_by, updated_at = now()
  returning * into v_row;
  return v_row;
end;
$function$
